import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {createMockProvider} from '../providers/mock/index.js';
import type {ChatSession} from '../types/session.js';

it('reports a string rejection with its cause while preserving the caller value [specs/hal-engine-config-hooks/spec.md#9]', async () => {
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const failures: Error[] = [];
  const orchestrator = createChatOrchestrator(
    createMockProvider(),
    new PromptBuilder({identity: 'Assistant'}),
    undefined,
    {
      hooks: {
        beforeModelResponse: async () => Promise.reject('policy rejected'),
        onError: async (_session, error) => {
          failures.push(error);
        },
      },
    }
  );

  const rejection: unknown = await orchestrator.processMessage(session).catch((error: unknown) => error);

  expect({rejection, failures: failures.map(error => ({isError: error instanceof Error, message: error.message, cause: error.cause}))}).toEqual({
    rejection: 'policy rejected',
    failures: [{isError: true, message: 'policy rejected', cause: 'policy rejected'}],
  });
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/onErrorCause.test.ts"
